script:
button { cursor: pointer; }
button:disabled { opacity: 0.5; cursor: not-allowed; }
a, button { transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease, transform 0.15s ease, box-shadow 0.15s ease; }
a:hover { opacity: 0.75; }
:focus-visible { outline: 2px solid var(--7e15180a-4410-4c55-a37f-0ee9f358d83f, #FF5D5D); outline-offset: 2px; }
[data-shop="variant-option"][data-selected="true"] {
	background: var(--7e15180a-4410-4c55-a37f-0ee9f358d83f, #FF5D5D);
	border-color: var(--7e15180a-4410-4c55-a37f-0ee9f358d83f, #FF5D5D);
	color: #FFFFFF;
}
[data-shop="cart-count"][data-empty="true"] { display: none; }
input, textarea { font-family: inherit; }
